! ============================================================
! VML 设备扩展库 — Fortran
!
! 使用示例:
!   ! 键盘 — 通过 PEEK/POKE MMIO 地址
!   call asm("SYSCALL 60")     ! 获取 KBD_DATA 地址
!
!   ! 鼠标 — 通过 PEEK/POKE MMIO 地址
!   call asm("SYSCALL 60")     ! 获取 MOUSE_X/Y/BUTTON 地址
!
!   ! 通用设备 — 通过设备 SYSCALL
!   call asm("SYSCALL 100")    ! DeviceOpen
!   call asm("SYSCALL 102")    ! DeviceRead
!   call asm("SYSCALL 103")    ! DeviceWrite
!   call asm("SYSCALL 104")    ! DeviceControl
!   call asm("SYSCALL 101")    ! DeviceClose
! ============================================================

! ============================================================
! 键盘操作 — MMIO 方式 (通过 PEEK/POKE)
!
! 键盘数据寄存器: 地址 0x60 (可通过 SYSCALL 60 码=20 查询)
! 键盘状态寄存器: 地址 0x64 (可通过 SYSCALL 60 码=21 查询)
!
! 读取按键:
!   1. 先用 SYSCALL 60 码=20 获取 KBD_DATA 地址
!   2. 通过 PEEK 读取地址上的值
!   3. 或通过 SYSCALL 5 (InputChar) 读取单个字符
!
! 检查按键可用:
!   1. 先用 SYSCALL 60 码=21 获取 KBD_STATUS 地址
!   2. 通过 PEEK 读取状态
!
! GetConfig 查询码:
!   码=20: KBD_DATA    — 返回键盘数据端口地址 (0x60)
!   码=21: KBD_STATUS  — 返回键盘状态端口地址 (0x64)
! ============================================================

! ============================================================
! 键盘操作 — 设备 SYSCALL 方式
!
! 打开键盘设备:
!   ! R0 = 设备名 "kbd" 的地址
!   call asm("SYSCALL 100")
!   ! 返回: R0 = 设备句柄 (>=0 成功)
!
! 读取键盘:
!   ! R0 = 设备句柄, R1 = 缓冲区地址, R2 = 字节数
!   call asm("SYSCALL 102")
!   ! 返回: R0 = 实际读取字节数
!
! 键盘控制命令 (DeviceControl):
!   命令=0: 获取键盘状态
!   命令=1: 检查是否有按键
!   命令=2: 清空键盘缓冲区
!
! 关闭键盘设备:
!   ! R0 = 设备句柄
!   call asm("SYSCALL 101")
! ============================================================

! ============================================================
! 鼠标操作 — MMIO 方式 (通过 PEEK/POKE)
!
! GetConfig 查询码:
!   码=22: MOUSE_X       — 返回鼠标 X 坐标地址 (0x300)
!   码=23: MOUSE_Y       — 返回鼠标 Y 坐标地址 (0x302)
!   码=24: MOUSE_BUTTON   — 返回鼠标按钮状态地址 (0x304)
!
! 读取鼠标位置:
!   1. 用 SYSCALL 60 获取地址
!   2. 用 PEEK 读取坐标值
!
! 按钮状态: 0=无按下, 1=左键, 2=右键, 4=中键
! ============================================================

! ============================================================
! 鼠标操作 — 设备 SYSCALL 方式
!
! 打开鼠标设备:
!   ! R0 = 设备名 "mouse" 的地址
!   call asm("SYSCALL 100")
!   ! 返回: R0 = 设备句柄
!
! 读取鼠标:
!   ! R0 = 设备句柄, R1 = 缓冲区地址, R2 = 字节数
!   call asm("SYSCALL 102")
!
! 关闭鼠标设备:
!   ! R0 = 设备句柄
!   call asm("SYSCALL 101")
! ============================================================

! ============================================================
! 通用设备操作 SYSCALL
!
! SYSCALL 100 — DeviceOpen
!   参数: R0 = 设备名称字符串地址
!   返回: R0 = 设备句柄 (>=0 成功, <0 失败)
!   支持设备: console, vga, kbd, mouse, timer, rtc, fs, speaker
!
! SYSCALL 101 — DeviceClose
!   参数: R0 = 设备句柄
!   返回: R0 = 0 成功, <0 失败
!
! SYSCALL 102 — DeviceRead
!   参数: R0 = 设备句柄, R1 = 缓冲区地址, R2 = 读取字节数
!   返回: R0 = 实际读取字节数, <0 错误
!
! SYSCALL 103 — DeviceWrite
!   参数: R0 = 设备句柄, R1 = 数据地址, R2 = 写入字节数
!   返回: R0 = 实际写入字节数, <0 错误
!
! SYSCALL 104 — DeviceControl
!   参数: R0 = 设备句柄, R1 = 命令号, R2 = 数据地址, R3 = 数据长度
!   返回: R0 = 命令结果, <0 错误
! ============================================================
